const s = ($input.first().json.severidad || 'not classified').toLowerCase();
const meta = {
  'not classified': { label: 'Sin clasificar', color: 0x95A5A6 },
  'information': { label: 'Informativa', color: 0x3498DB },
  'warning': { label: 'Advertencia', color: 0xF1C40F },
  'average': { label: 'Media', color: 0xE67E22 },
  'high': { label: 'Alta', color: 0xE74C3C },
  'disaster': { label: 'Desastre', color: 0x992222 }
};
const m = meta[s] || meta['not classified'];
const c = $input.first().json;
return [{ json: {
  title: `[${m.label}] ${c.host}: ${c.problema}`,
  color: m.color,
  fields: [
    { name: 'Host', value: c.host, inline: true },
    { name: 'Severidad', value: m.label, inline: true },
    { name: 'Evento', value: c.eventid || 'n/a', inline: true },
    { name: 'Problema', value: c.problema, inline: false }
  ],
  buttons: [
    { id: 'detalle', label: 'Detalle' },
    { id: 'mantenimiento', label: 'Mantenimiento' },
    { id: 'ack', label: 'Ack' }
  ],
  url: c.url || undefined
}}];
